const rows = $input.all().map(item => item.json);

const findLevel = (level) => rows.find(r => r.risk_level === level) 
  || { total_clientes: "0", ingresos_totales: "0", perdida_esperada: "0" };

const alto = findLevel('Alto');
const medio = findLevel('Medio');
const bajo = findLevel('Bajo');

const totalClientes = Number(alto.total_clientes) + Number(medio.total_clientes) + Number(bajo.total_clientes);

// Pérdida esperada TOTAL (suma ponderada por probabilidad)
const perdidaTotal = (
  Number(alto.perdida_esperada) +
  Number(medio.perdida_esperada) +
  Number(bajo.perdida_esperada)
).toFixed(2);

// Pérdida esperada ANUAL
const perdidaTotalAnual = (Number(perdidaTotal) * 12).toFixed(2);

return [{
  json: {
    alto_clientes: alto.total_clientes,
    alto_ingresos: alto.ingresos_totales,
    alto_perdida: alto.perdida_esperada,

    medio_clientes: medio.total_clientes,
    medio_ingresos: medio.ingresos_totales,
    medio_perdida: medio.perdida_esperada,

    bajo_clientes: bajo.total_clientes,
    bajo_ingresos: bajo.ingresos_totales,
    bajo_perdida: bajo.perdida_esperada,

    total_clientes: String(totalClientes),
    perdida_esperada_total: perdidaTotal,
    perdida_esperada_anual: perdidaTotalAnual
  }
}];
